<script setup>
import {useAdminFeedback} from '../../composables/useAdminToast.js';
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {supabase} from '../../lib/supabase';
const props=defineProps({battle:{type:Object,required:true}}),emit=defineEmits(['update']);
const busy=ref(false),error=ref(''),notice=ref(''),reason=ref(''),finishOpen=ref(false),resetPlayer=ref(''),winner=ref('draw'),events=ref([]),historyError=ref(false);
const finished=computed(()=>props.battle.status==='finished'||Boolean(props.battle.winner));let channel,version=0;
async function loadHistory(){const request=++version;const {data,error:failure}=await supabase.from('battle_events').select('id,type,source_player,target_player,payload,created_at').eq('battle_id',props.battle.id).order('created_at',{ascending:false}).limit(100);if(request!==version)return;historyError.value=Boolean(failure);if(!failure)events.value=data??[];else adminToast.danger('Riwayat aksi belum dapat dimuat. Coba muat ulang.');}
async function control(action){if(busy.value)return;if(action==='finish'&&!reason.value.trim()){error.value='Isi alasan mengakhiri pertandingan.';return;}busy.value=true;error.value='';notice.value='';try{const {data,error:failure}=await supabase.rpc('teacher_control_battle',{p_code:props.battle.code,p_action:action,p_reason:reason.value,p_winner:winner.value});if(failure)throw failure;if(!data?.ok)throw new Error(data?.message||'Aksi belum dapat diterapkan.');emit('update',data.battle);reason.value='';finishOpen.value=false;notice.value=action==='pause'?'Battle dijeda. Timer dan aksi pemain dibekukan.':action==='resume'?'Battle dilanjutkan dengan sisa waktu yang sama.':'Pertandingan telah diakhiri.';await loadHistory();}catch(e){error.value=e?.message||'Kontrol guru belum dapat dijalankan.';}finally{busy.value=false;}}
async function resetAccess(){if(busy.value||!resetPlayer.value)return;busy.value=true;error.value='';notice.value='';try{const side=resetPlayer.value;const {data,error:failure}=await supabase.rpc('teacher_reset_battle_access',{p_code:props.battle.code,p_player:side});if(failure)throw failure;if(!data?.ok)throw new Error(data?.message||'Akses gagal diperbarui.');emit('update',{id:props.battle.id,...data});resetPlayer.value='';notice.value=`Akses ${side==='p1'?'Player 1':'Player 2'} diperbarui. Bagikan kode pribadi terbaru yang terlihat di bawah.`;await loadHistory();}catch(e){error.value=e?.message||'Akses gagal diperbarui.';}finally{busy.value=false;}}
const eventText=e=>e.payload?.message||e.payload?.skill_name||e.payload?.action||e.type;
const csvCell=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
function downloadHistory(){const lines=[['Waktu','Aksi','Pemain','Target','Keterangan','Alasan'],...events.value.map(e=>[e.created_at,e.type,e.source_player,e.target_player,eventText(e),e.payload?.reason])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`battle-${props.battle.code}-riwayat.csv`;a.click();adminToast.success('Riwayat battle siap diunduh dalam format CSV.');setTimeout(()=>URL.revokeObjectURL(url),1000);}
onMounted(()=>{void loadHistory();channel=supabase.channel(`teacher-controls:${props.battle.id}`).on('postgres_changes',{event:'UPDATE',schema:'public',table:'battle_sessions',filter:`id=eq.${props.battle.id}`},payload=>emit('update',payload.new)).on('postgres_changes',{event:'INSERT',schema:'public',table:'battle_events',filter:`battle_id=eq.${props.battle.id}`},()=>void loadHistory()).subscribe();});
onBeforeUnmount(()=>{version++;if(channel)supabase.removeChannel(channel);});
const adminToast=useAdminFeedback({error,success:notice,scope:'battle/TeacherBattleControls'});
</script>
<template>
 <section class="teacher-controls" aria-label="Kontrol guru"><header><div><span>KHUSUS GURU</span><h3>Kelola pertandingan</h3></div><b>{{ finished?'Selesai':battle.teacher_paused?'Dijeda':'Berjalan' }}</b></header>
  <p>Jeda saat koneksi atau pembaca kartu bermasalah. Waktu giliran, kuis, AP, dan cooldown dipertahankan.</p>
  <label v-if="!finished">Catatan guru<input v-model="reason" maxlength="300" placeholder="Contoh: mengganti perangkat Player 1" :disabled="busy"></label>
  <div v-if="!finished" class="teacher-actions"><button type="button" :disabled="busy" @click="control(battle.teacher_paused?'resume':'pause')">{{ battle.teacher_paused?'▶ Lanjutkan battle':'Ⅱ Jeda battle' }}</button><button type="button" class="secondary danger" :disabled="busy" @click="finishOpen=!finishOpen;resetPlayer=''">Akhiri pertandingan…</button></div>
  <fieldset v-if="finishOpen&&!finished"><legend>Konfirmasi hasil akhir</legend><p>Hasil disimpan dan aksi berikutnya dihentikan. Isi alasan pada catatan guru sebelum mengakhiri.</p><label>Hasil<select v-model="winner" :disabled="busy"><option value="draw">Seri</option><option value="p1">{{ battle.player1_name||'Player 1' }} menang</option><option value="p2">{{ battle.player2_name||'Player 2' }} menang</option></select></label><div class="teacher-actions"><button type="button" class="danger" :disabled="busy||!reason.trim()" @click="control('finish')">Konfirmasi akhiri battle</button><button type="button" class="secondary" :disabled="busy" @click="finishOpen=false">Batal</button></div></fieldset>
  <details v-if="!finished" class="teacher-reconnect"><summary>Bantu pemain tersambung kembali / ganti perangkat</summary><ol><li>Jeda battle agar waktu tidak terbuang.</li><li>Di tab semula, muat ulang halaman. Akses tersimpan selama tab masih tersedia.</li><li>Untuk perangkat baru, buka QR pemain lalu masukkan kode pribadinya. Jika perangkat lama hilang atau link pernah dibagikan, perbarui akses di bawah.</li><li>Pastikan pemain sudah masuk, lalu lanjutkan battle.</li></ol><div class="teacher-actions"><button v-for="side in ['p1','p2']" :key="side" type="button" class="secondary" :disabled="busy" @click="resetPlayer=side;finishOpen=false">Perbarui akses Player {{ side==='p1'?'1':'2' }}</button></div><div v-if="resetPlayer" class="reset-confirm"><p>Putuskan akses lama Player {{ resetPlayer==='p1'?'1':'2' }}? Pemain harus masuk lagi memakai kode baru.</p><div class="teacher-actions"><button type="button" :disabled="busy" @click="resetAccess">Ya, buat kode baru</button><button type="button" class="secondary" :disabled="busy" @click="resetPlayer=''">Batal</button></div></div></details>
  <p v-if="error" class="teacher-error" role="alert">{{ error }}</p><p v-if="notice" class="teacher-notice" role="status">{{ notice }}</p>
  <details class="teacher-history"><summary>Riwayat aksi · {{ events.length }} terbaru</summary><div class="teacher-actions"><button type="button" class="secondary" @click="loadHistory">Muat ulang</button><button type="button" class="secondary" :disabled="!events.length||historyError" @click="downloadHistory">Unduh CSV</button></div><p v-if="historyError" role="alert">Riwayat belum dapat dimuat. Coba muat ulang.</p><ol v-else><li v-for="event in events" :key="event.id"><time>{{ new Date(event.created_at).toLocaleTimeString('id-ID') }}</time><div><strong>{{ event.source_player==='p1'?(battle.player1_name||'Player 1'):event.source_player==='p2'?(battle.player2_name||'Player 2'):event.type.startsWith('teacher_')?'Guru':'Sistem' }}</strong><span>{{ eventText(event) }}</span><small v-if="event.payload?.reason">{{ event.payload.reason }}</small></div></li><li v-if="!events.length">Belum ada aksi.</li></ol><small>Ekspor berisi maksimal 100 aksi terbaru yang ditampilkan di sini.</small></details>
 </section>
</template>
<style scoped>
.teacher-controls{border:1px solid #cadfc6;background:#f5faf0;border-radius:14px;padding:20px;margin:20px 0;color:#244e32}.teacher-controls *{box-sizing:border-box}.teacher-controls header{display:flex;align-items:center;justify-content:space-between;gap:15px}.teacher-controls header span{font-size:9px;font-weight:800;letter-spacing:.15em;color:#72966c}.teacher-controls h3{margin:5px 0;font-size:20px}.teacher-controls header>b{background:#e1efd5;padding:7px 12px;border-radius:20px;font-size:11px}.teacher-controls p,.teacher-controls li{font-size:12px;line-height:1.8}.teacher-controls>p{color:#63805e}.teacher-controls label{display:grid;gap:7px;font-size:11px;font-weight:700;margin:14px 0}.teacher-controls input,.teacher-controls select{width:100%;min-width:0;border:1px solid #cddfc7;border-radius:8px;padding:11px;background:#fff;color:#315a3d;font:inherit}.teacher-actions{display:flex;flex-wrap:wrap;gap:9px;margin:12px 0}.teacher-controls button{padding:10px 13px;border:1px solid #2e7142;border-radius:8px;background:#2e7142;color:#fff;font:700 11px Inter,Arial,sans-serif;cursor:pointer}.teacher-controls button.secondary{background:#fff;color:#3c6f43;border-color:#c7d9c0}.teacher-controls button.danger{background:#94512f;border-color:#94512f;color:#fff}.teacher-controls button.secondary.danger{background:#fff;color:#94512f;border-color:#e1c5ad}.teacher-controls button:disabled{opacity:.55;cursor:default}.teacher-controls :is(button,input,select,summary):focus-visible{outline:3px solid #348b99;outline-offset:3px}.teacher-controls fieldset{border:1px solid #dfc7ad;border-radius:10px;padding:16px;margin:16px 0;background:#fff9ee}.teacher-controls legend{font-size:12px;font-weight:750}.teacher-controls details{border-top:1px solid #d6e2cd;padding-top:15px;margin-top:18px}.teacher-controls summary{cursor:pointer;font-size:12px;font-weight:750}.teacher-controls ol{padding-left:20px}.reset-confirm{padding:13px;border:1px solid #e0c9a8;border-radius:9px;background:#fff8e8}.teacher-controls .teacher-error{color:#9a4026;background:#fff1e8;padding:11px;border-radius:8px}.teacher-controls .teacher-notice{color:#2d673b;background:#e4f2da;padding:11px;border-radius:8px}.teacher-history ol{list-style:none;padding:0;max-height:280px;overflow:auto;background:#fff;border-radius:9px}.teacher-history li{display:flex;gap:14px;padding:12px;border-bottom:1px solid #e0ead9}.teacher-history li div{display:grid;gap:3px}.teacher-history time,.teacher-history small{font-size:10px;color:#7c8d74}.teacher-history li span{overflow-wrap:anywhere}.teacher-history>small{font-size:10px;color:#6f8464}
</style>
